(() => {
  const {$}=Atlas;const mode=document.body.dataset.auth;
  document.querySelectorAll('[data-toggle-password]').forEach(button=>button.onclick=()=>{const input=$('#'+button.dataset.togglePassword);const show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Ocultar':'Mostrar';button.setAttribute('aria-label',(show?'Ocultar':'Mostrar')+' senha');button.setAttribute('aria-pressed',String(show));});
  const form=$('#account-form');const password=$('#password');const confirm=$('#password-confirm');
  if(confirm){const compare=()=>confirm.setCustomValidity(confirm.value&&password.value!==confirm.value?'As senhas precisam ser iguais.':'');confirm.addEventListener('input',compare);password.addEventListener('input',compare);}
  if($('#password-strength'))password.addEventListener('input',()=>{const p=password.value;const level=Math.min(4,(p.length>=8?1:0)+(p.length>=12?1:0)+(/[a-z]/.test(p)&&/[A-Z]/.test(p)?1:0)+(/\d/.test(p)&&/[^a-zA-Z0-9]/.test(p)?1:0));$('#password-strength').dataset.level=level;$('#strength-label').textContent=!p?'Use pelo menos 8 caracteres.':['Ainda muito curta','Básica','Razoável','Boa','Forte'][level];});
  form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const signup=mode==='signup';const recover=mode==='recover';$('#form-feedback').hidden=false;$('#form-feedback').innerHTML=`<b>${recover?'Interface de recuperação validada.':signup?'Cadastro pronto para integração.':'Login pronto para integração.'}</b><p>${recover?'O envio de e-mail ainda depende do backend. Nenhuma mensagem foi enviada.':'Este é o frontend: nenhum usuário foi criado ou autenticado e nenhuma senha foi armazenada.'}</p><a class="btn-gold" href="home.html">Explorar a home demonstrativa ↗</a>`;if(password)password.value='';if(confirm)confirm.value='';if($('#password-strength')){$('#password-strength').dataset.level='0';$('#strength-label').textContent='Use pelo menos 8 caracteres.';}$('#form-feedback').focus();};
})();
